/**
 * Brand-rejection tests for CreateTenantModal — C1 TranslatedString rollout.
 *
 * The Field component is file-private so we test via CreateTenantModalProps
 * which passes through to the shared Modal. The key surface is that Modal.title
 * and Modal.eyebrow must reject raw strings.
 */

import { describe, it } from "vitest";
import { CreateTenantModal } from "../../src/tenants/CreateTenantModal";
import type { TranslatedString } from "@omnicore-platform/platform-chrome";

void CreateTenantModal;
void (null as unknown as TranslatedString);

// CreateTenantModal hard-wires title/eyebrow from the catalog (m.*() calls).
// This test is a compile-time smoke check: the file must typecheck clean.
// Brand enforcement on Modal.title/eyebrow is tested in Modal.brand.test.tsx.
const _smoke: typeof CreateTenantModal = CreateTenantModal;
void _smoke;

describe("CreateTenantModal — TranslatedString brand (compile-time)", () => {
  it("compiles clean — all Field label/hint props use m.*() TranslatedString values", () => {
    // The @ts-expect-error directives in Modal.brand.test.tsx cover Modal.title/eyebrow.
    // CreateTenantModal itself uses m.*() for all label/hint values, which are already
    // TranslatedString — no unsafeAsTranslated calls needed.
  });
});


