import { describe, expect, it, vi, beforeEach } from "vitest";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { CreateTenantModal } from "../../src/tenants/CreateTenantModal";

beforeEach(() => {
  vi.restoreAllMocks();
});

function envelope(payload: unknown, status = 201): Response {
  return new Response(JSON.stringify({ data: payload }), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

describe("CreateTenantModal", () => {
  it("renders the modal with Create + Dry run disabled until both fields are valid", () => {
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    expect(
      screen.getByRole("dialog", { name: /create organization/i }),
    ).toBeInTheDocument();
    expect(screen.getByTestId("create-tenant-submit")).toBeDisabled();
    expect(screen.getByTestId("create-tenant-dry-run")).toBeDisabled();
  });

  it("auto-suggests a slug from the name until the slug is touched", async () => {
    const user = userEvent.setup();
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    const nameInput = screen.getByTestId("create-tenant-name");
    const slugInput = screen.getByTestId(
      "create-tenant-slug",
    ) as HTMLInputElement;

    await user.type(nameInput, "Acme Industries");
    expect(slugInput.value).toBe("acme-industries");

    await user.clear(slugInput);
    await user.type(slugInput, "acme");
    await user.type(nameInput, " Inc");
    expect(slugInput.value).toBe("acme");
  });

  it("submits the create and forwards trial_days when selected", async () => {
    const user = userEvent.setup();
    const onCreated = vi.fn();
    const onClose = vi.fn();
    const spy = vi.fn(async () =>
      envelope({
        tenant: {
          id: "new-t",
          name: "Acme",
          slug: "acme",
          status: "trial",
          created_at: "2026-05-12T12:00:00Z",
          updated_at: "2026-05-12T12:00:00Z",
        },
        dry_run_planned: false,
      }),
    );
    globalThis.fetch = spy as unknown as typeof fetch;

    render(
      <CreateTenantModal open onCreated={onCreated} onClose={onClose} />,
    );
    await user.type(screen.getByTestId("create-tenant-name"), "Acme");
    await user.click(screen.getByTestId("create-tenant-trial-90"));
    await user.click(screen.getByTestId("create-tenant-submit"));

    await waitFor(() => expect(onCreated).toHaveBeenCalledTimes(1));
    expect(onClose).toHaveBeenCalledTimes(1);

    const calls = spy.mock.calls as unknown as [string, RequestInit][];
    const body = JSON.parse(String(calls[0]?.[1]?.body));
    expect(body.trial_days).toBe(90);
  });

  it("omits trial_days from the body when 'No trial' is selected (default)", async () => {
    const user = userEvent.setup();
    const spy = vi.fn(async () =>
      envelope({
        tenant: {
          id: "new-t",
          name: "Acme",
          slug: "acme",
          status: "active",
          created_at: "2026-05-12T12:00:00Z",
          updated_at: "2026-05-12T12:00:00Z",
        },
        dry_run_planned: false,
      }),
    );
    globalThis.fetch = spy as unknown as typeof fetch;

    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    await user.type(screen.getByTestId("create-tenant-name"), "Acme");
    await user.click(screen.getByTestId("create-tenant-submit"));

    await waitFor(() => expect(spy).toHaveBeenCalled());
    const calls = spy.mock.calls as unknown as [string, RequestInit][];
    const body = JSON.parse(String(calls[0]?.[1]?.body));
    expect(body.trial_days).toBeUndefined();
  });

  it("Dry run shows the preview banner and does NOT close the modal", async () => {
    const user = userEvent.setup();
    const onCreated = vi.fn();
    const onClose = vi.fn();
    globalThis.fetch = vi.fn(async () =>
      envelope({
        tenant: {
          id: "00000000-0000-0000-0000-000000000000",
          name: "Preview",
          slug: "preview",
          status: "active",
          created_at: "",
          updated_at: "",
        },
        dry_run_planned: true,
      }),
    ) as unknown as typeof fetch;

    render(
      <CreateTenantModal open onCreated={onCreated} onClose={onClose} />,
    );
    await user.type(screen.getByTestId("create-tenant-name"), "Preview");
    await user.click(screen.getByTestId("create-tenant-dry-run"));

    await waitFor(() => {
      expect(screen.getByTestId("create-tenant-preview")).toBeInTheDocument();
    });
    expect(onCreated).not.toHaveBeenCalled();
    expect(onClose).not.toHaveBeenCalled();
  });

  it("surfaces the BFF error inline when the create fails", async () => {
    const user = userEvent.setup();
    globalThis.fetch = vi.fn(async () =>
      new Response(
        JSON.stringify({
          error: { code: "already_exists", message: "slug taken" },
        }),
        { status: 409, headers: { "Content-Type": "application/json" } },
      ),
    ) as unknown as typeof fetch;

    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    await user.type(screen.getByTestId("create-tenant-name"), "Dup");
    await user.click(screen.getByTestId("create-tenant-submit"));

    await waitFor(() => {
      expect(screen.getByTestId("create-tenant-error")).toBeInTheDocument();
    });
    expect(screen.getByTestId("create-tenant-error")).toHaveTextContent(
      /slug taken/i,
    );
  });

  it("invokes onClose when the close button is clicked", async () => {
    const user = userEvent.setup();
    const onClose = vi.fn();
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={onClose} />,
    );
    await user.click(screen.getByRole("button", { name: /close modal/i }));
    expect(onClose).toHaveBeenCalledTimes(1);
  });

  it("invokes onClose when Escape is pressed inside the panel", () => {
    const onClose = vi.fn();
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={onClose} />,
    );
    fireEvent.keyDown(screen.getByTestId("modal-panel"), { key: "Escape" });
    expect(onClose).toHaveBeenCalled();
  });

  // Trial period is an org-only concept. When the modal opens from an
  // organization's Workspaces tab (parentId is preset to the org's id),
  // we're creating a sub-workspace — the Trial field must not appear.
  it("hides the Trial period field when parentId is preset (creating a workspace)", () => {
    render(
      <CreateTenantModal
        open
        parentId="org-uuid-1"
        onCreated={() => {}}
        onClose={() => {}}
      />,
    );
    expect(screen.queryByTestId("create-tenant-trial")).not.toBeInTheDocument();
  });

  // Defense in depth: even if a future state-leak put trialDays > 0,
  // the submit payload must never carry trial_days when parentLocked.
  it("does not send trial_days in the payload when parentId is preset", async () => {
    const PARENT_ORG_ID = "11111111-2222-3333-4444-555555555555";
    const user = userEvent.setup();
    const spy = vi.fn(async () =>
      envelope({
        tenant: {
          id: "new-ws",
          name: "Eng",
          slug: "eng",
          parent_id: PARENT_ORG_ID,
          status: "active",
          created_at: "2026-05-12T12:00:00Z",
          updated_at: "2026-05-12T12:00:00Z",
        },
        dry_run_planned: false,
      }),
    );
    globalThis.fetch = spy as unknown as typeof fetch;

    render(
      <CreateTenantModal
        open
        parentId={PARENT_ORG_ID}
        onCreated={() => {}}
        onClose={() => {}}
      />,
    );
    await user.type(screen.getByTestId("create-tenant-name"), "Engineering");
    await user.click(screen.getByTestId("create-tenant-submit"));

    await waitFor(() => expect(spy).toHaveBeenCalled());
    const calls = spy.mock.calls as unknown as [string, RequestInit][];
    const body = JSON.parse(String(calls[0]?.[1]?.body));
    expect(body.parent_id).toBe(PARENT_ORG_ID);
    expect(body.trial_days).toBeUndefined();
  });

  // ── Zod validation (Stage 2) ─────────────────────────────────────────────

  it("keeps submit disabled when name is invalid (empty after trim)", async () => {
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    // Only type spaces — displayNameSchema rejects empty-after-trim
    const nameInput = screen.getByTestId("create-tenant-name");
    nameInput.focus();
    // Leave name empty
    expect(screen.getByTestId("create-tenant-submit")).toBeDisabled();
  });

  it("keeps submit disabled when slug is invalid (contains special chars)", async () => {
    const user = userEvent.setup();
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    // Type a name (auto-populates slug), then override slug with invalid chars
    await user.type(screen.getByTestId("create-tenant-name"), "Good Name");
    await user.clear(screen.getByTestId("create-tenant-slug"));
    await user.type(screen.getByTestId("create-tenant-slug"), "Bad Slug!");

    expect(screen.getByTestId("create-tenant-submit")).toBeDisabled();
  });

  it("shows slug error on blur when slug contains invalid characters", async () => {
    const user = userEvent.setup();
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    const slugInput = screen.getByTestId("create-tenant-slug");
    await user.type(slugInput, "Bad Slug!");
    await user.tab(); // blur

    expect(await screen.findByRole("alert")).toBeInTheDocument();
  });

  it("enables submit once both name and slug are valid", async () => {
    const user = userEvent.setup();
    render(
      <CreateTenantModal open onCreated={() => {}} onClose={() => {}} />,
    );
    await user.type(screen.getByTestId("create-tenant-name"), "Good Name");
    // slug auto-suggests "good-name" which is valid
    expect(screen.getByTestId("create-tenant-submit")).toBeEnabled();
  });
});


