void Modal;
void (null as unknown as TranslatedString);

// Simulate what DeleteTenantModal used to do — passing a raw string to Modal title.
// After the brand is enforced this must be a type error.
// @ts-expect-error TranslatedString brand: DeleteTenantModal passes raw title to Modal
const _deleteTitleRaw: Parameters<typeof Modal>[0]["title"] = "Suspend this organization first";
void _deleteTitleRaw;

// @ts-expect-error TranslatedString brand: DeleteTenantModal passes raw eyebrow to Modal
const _deleteEyebrowRaw: NonNullable<Parameters<typeof Modal>[0]["eyebrow"]> = "Confirm";
void _deleteEyebrowRaw;

describe("DeleteTenantModal — TranslatedString brand (compile-time)", () => {
  it("Modal.title and Modal.eyebrow reject raw string literals at compile time", () => {
    // The @ts-expect-error directives above prove the brand is enforced.
    // DeleteTenantModal call sites now use unsafeAsTranslated() with i18n-allow comments.
  });
});


