import { describe, expect, it, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { DeleteTenantModal } from "../../src/tenants/DeleteTenantModal";
import type { AdminTenant } from "../../src/api/tenants";

const ACME: AdminTenant = {
  id: "t1",
  name: "Acme",
  slug: "acme",
  status: "active",
  created_at: "2026-05-10T12:00:00Z",
  updated_at: "2026-05-10T12:00:00Z",
};

beforeEach(() => {
  vi.restoreAllMocks();
});

describe("DeleteTenantModal", () => {
  it("renders the confirm body with the tenant name", () => {
    render(
      <DeleteTenantModal
        open
        tenant={ACME}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    const body = screen.getByTestId("delete-tenant-body");
    expect(body).toHaveTextContent(/Acme/);
    expect(body).toHaveTextContent(/blocks login/);
  });

  it("calls deleteTenant + fires onDeleted on confirm", async () => {
    const user = userEvent.setup();
    const onDeleted = vi.fn();
    const onClose = vi.fn();
    const fetchSpy = vi.fn(async () =>
      new Response(
        JSON.stringify({ data: { ...ACME, status: "suspended" } }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      ),
    );
    globalThis.fetch = fetchSpy as unknown as typeof fetch;

    render(
      <DeleteTenantModal
        open
        tenant={ACME}
        onClose={onClose}
        onDeleted={onDeleted}
      />,
    );
    await user.click(screen.getByTestId("delete-tenant-confirm"));

    await waitFor(() => expect(onDeleted).toHaveBeenCalledTimes(1));
    expect(onDeleted.mock.calls[0]![0]).toMatchObject({
      id: "t1",
      status: "suspended",
    });
    expect(onClose).toHaveBeenCalledTimes(1);

    const calls = fetchSpy.mock.calls as unknown as [string, RequestInit][];
    expect(calls[0]?.[0]).toBe("/api/v1/admin/tenants/t1");
    expect(calls[0]?.[1]?.method).toBe("DELETE");
  });

  it("blocks delete when the org has active child workspaces", () => {
    render(
      <DeleteTenantModal
        open
        tenant={ACME}
        childWorkspaceNames={["Acme East", "Acme West"]}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    expect(
      screen.getByText(/Suspend this organization first/i),
    ).toBeInTheDocument();
    const list = screen.getByTestId("delete-tenant-blocked-children");
    expect(list).toHaveTextContent("Acme East");
    expect(list).toHaveTextContent("Acme West");
    expect(
      screen.queryByTestId("delete-tenant-confirm"),
    ).not.toBeInTheDocument();
  });

  it("collapses to the normal confirm flow when childWorkspaceNames is empty", () => {
    render(
      <DeleteTenantModal
        open
        tenant={ACME}
        childWorkspaceNames={[]}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    expect(screen.getByTestId("delete-tenant-confirm")).toBeInTheDocument();
  });

  it("surfaces the BFF error inline when delete fails", async () => {
    const user = userEvent.setup();
    globalThis.fetch = vi.fn(async () =>
      new Response(
        JSON.stringify({
          error: { code: "not_found", message: "tenant not found" },
        }),
        { status: 404, headers: { "Content-Type": "application/json" } },
      ),
    ) as unknown as typeof fetch;

    render(
      <DeleteTenantModal
        open
        tenant={ACME}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    await user.click(screen.getByTestId("delete-tenant-confirm"));

    await waitFor(() => {
      expect(screen.getByTestId("delete-tenant-error")).toBeInTheDocument();
    });
    expect(screen.getByTestId("delete-tenant-error")).toHaveTextContent(
      /tenant not found/i,
    );
  });

  it("shows singular child label when exactly one active child workspace", () => {
    render(
      <DeleteTenantModal
        open
        tenant={ACME}
        childWorkspaceNames={["Acme East"]}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    const body = screen.getByTestId("delete-tenant-body");
    // length === 1 → no "s" suffix
    expect(body).toHaveTextContent(/1/);
    expect(body).not.toHaveTextContent(/workspaces/i);
  });

  it("resets to idle state when re-opened after an error", async () => {
    const user = userEvent.setup();
    globalThis.fetch = vi.fn(async () =>
      new Response(
        JSON.stringify({ error: { code: "internal", message: "db error" } }),
        { status: 500, headers: { "Content-Type": "application/json" } },
      ),
    ) as unknown as typeof fetch;

    const { rerender } = render(
      <DeleteTenantModal
        open
        tenant={ACME}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    await user.click(screen.getByTestId("delete-tenant-confirm"));
    await waitFor(() =>
      expect(screen.getByTestId("delete-tenant-error")).toBeInTheDocument(),
    );

    // Close and reopen: error should clear
    rerender(
      <DeleteTenantModal
        open={false}
        tenant={ACME}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    rerender(
      <DeleteTenantModal
        open
        tenant={ACME}
        onClose={() => {}}
        onDeleted={() => {}}
      />,
    );
    expect(screen.queryByTestId("delete-tenant-error")).not.toBeInTheDocument();
    expect(screen.getByTestId("delete-tenant-confirm")).toBeInTheDocument();
  });
});


