import { describe, expect, it, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";

import { EditTenantModal } from "../../src/tenants/EditTenantModal";
import type { AdminTenant } from "../../src/api/tenants";

beforeEach(() => {
  vi.restoreAllMocks();
});

function makeTenant(overrides: Partial<AdminTenant> = {}): AdminTenant {
  return {
    id: "t1",
    name: "Acme",
    slug: "acme",
    created_at: "2026-05-12T12:00:00Z",
    updated_at: "2026-05-12T12:00:00Z",
    status: "active",
    ...overrides,
  };
}

describe("EditTenantModal", () => {
  it("renders with the tenant's current name + slug and Save disabled", () => {
    render(
      <EditTenantModal
        open
        tenant={makeTenant({ name: "Acme", slug: "acme" })}
        onClose={() => {}}
        onUpdated={() => {}}
      />,
    );
    expect(
      (screen.getByTestId("edit-tenant-name") as HTMLInputElement).value,
    ).toBe("Acme");
    expect(
      (screen.getByTestId("edit-tenant-slug") as HTMLInputElement).value,
    ).toBe("acme");
    expect(screen.getByTestId("edit-tenant-save")).toBeDisabled();
  });

  it("enables Save when name or slug is dirty + valid", async () => {
    const user = userEvent.setup();
    render(
      <EditTenantModal
        open
        tenant={makeTenant()}
        onClose={() => {}}
        onUpdated={() => {}}
      />,
    );
    await user.clear(screen.getByTestId("edit-tenant-name"));
    await user.type(screen.getByTestId("edit-tenant-name"), "Acme Inc");
    expect(screen.getByTestId("edit-tenant-save")).toBeEnabled();
  });

  it("rejects empty name as invalid", async () => {
    const user = userEvent.setup();
    render(
      <EditTenantModal
        open
        tenant={makeTenant()}
        onClose={() => {}}
        onUpdated={() => {}}
      />,
    );
    await user.clear(screen.getByTestId("edit-tenant-name"));
    expect(screen.getByTestId("edit-tenant-save")).toBeDisabled();
  });

  it("PATCHes only the dirty fields and emits the post-image", async () => {
    const spy = vi.fn(async () =>
      new Response(
        JSON.stringify({
          data: {
            ...makeTenant(),
            name: "Acme Inc",
            updated_at: "2026-05-12T13:00:00Z",
          },
        }),
        { status: 200, headers: { "Content-Type": "application/json" } },
      ),
    );
    globalThis.fetch = spy as unknown as typeof fetch;

    const onUpdated = vi.fn();
    const onClose = vi.fn();
    const user = userEvent.setup();

    render(
      <EditTenantModal
        open
        tenant={makeTenant()}
        onClose={onClose}
        onUpdated={onUpdated}
      />,
    );

    await user.clear(screen.getByTestId("edit-tenant-name"));
    await user.type(screen.getByTestId("edit-tenant-name"), "Acme Inc");
    await user.click(screen.getByTestId("edit-tenant-save"));

    await waitFor(() => {
      expect(onUpdated).toHaveBeenCalled();
    });
    expect(onClose).toHaveBeenCalled();

    const calls = spy.mock.calls as unknown as [string, RequestInit][];
    expect(calls[0]?.[0]).toBe("/api/v1/admin/tenants/t1");
    expect(calls[0]?.[1]?.method).toBe("PATCH");
    expect(calls[0]?.[1]?.body).toBe(JSON.stringify({ name: "Acme Inc" }));
  });

  it("surfaces the server error on a non-2xx response", async () => {
