/**
 * data-i18n-allow attribute regression tests for TenantsTable.
 *
 * Dynamic BFF data (tenant name, slug, owner display_name) render as
 * non-registry strings that would trigger false [i18n-leak] warnings
 * unless the wrapping element carries data-i18n-allow="data".
 *
 * - Tenant name: "Acme Corp" → definitely triggers leak without attribute
 * - Slug: "acme-corp" → has letters, not email/UUID, would trigger leak
 * - Owner display_name: "Alice Liu" → triggers leak without attribute
 * - Owner email: self-suppressed by the observer's EMAIL_RE pattern
 *
 * TDD Step D-admin / TenantsTable
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import { TenantsTable } from "../../src/tenants/TenantsTable";

beforeEach(() => {
  vi.restoreAllMocks();
});

afterEach(() => {
  vi.restoreAllMocks();
});

function envelope(payload: unknown, status = 200): Response {
  return new Response(JSON.stringify({ data: payload }), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

describe("TenantsTable — data-i18n-allow attribute", () => {
  it("wraps tenant name in a data-i18n-allow='data' ancestor", async () => {
    globalThis.fetch = vi.fn(async () =>
      envelope({
        tenants: [
          {
            id: "t1",
            name: "Acme Corp",
            slug: "acme-corp",
            created_at: "2026-05-11T12:00:00Z",
            updated_at: "2026-05-11T12:00:00Z",
          },
        ],
        next_page_token: "",
      }),
    ) as unknown as typeof fetch;

    render(<TenantsTable />);

    await waitFor(() => {
      expect(screen.getByTestId("tenants-row-t1")).toBeInTheDocument();
    });

    const row = screen.getByTestId("tenants-row-t1");
    const allowedContainer = row.querySelector('[data-i18n-allow="data"]');
    expect(allowedContainer).not.toBeNull();
    expect(allowedContainer?.textContent).toContain("Acme Corp");
  });

  it("wraps tenant slug in a data-i18n-allow='data' ancestor", async () => {
    globalThis.fetch = vi.fn(async () =>
      envelope({
        tenants: [
          {
            id: "t1",
            name: "Acme Corp",
            slug: "acme-corp",
            created_at: "2026-05-11T12:00:00Z",
            updated_at: "2026-05-11T12:00:00Z",
          },
        ],
        next_page_token: "",
      }),
    ) as unknown as typeof fetch;

    render(<TenantsTable />);

    await waitFor(() => {
      expect(screen.getByTestId("tenants-row-t1")).toBeInTheDocument();
    });

    const row = screen.getByTestId("tenants-row-t1");
    // The slug span must be inside a data-i18n-allow="data" ancestor
    const slugEl = Array.from(row.querySelectorAll('[data-i18n-allow="data"]')).find(
      (el) => el.textContent?.includes("acme-corp"),
    );
    expect(slugEl).toBeDefined();
  });

  it("wraps owner display_name in a data-i18n-allow='data' ancestor", async () => {
    globalThis.fetch = vi.fn(async () =>
      envelope({
        tenants: [
          {
            id: "t1",
            name: "Acme Corp",
            slug: "acme-corp",
            created_at: "2026-05-11T12:00:00Z",
            updated_at: "2026-05-11T12:00:00Z",
            owner: {
              user_id: "11111111-1111-1111-1111-111111111111",
              display_name: "Alice Liu",
              email: "alice@example.com",
            },
          },
        ],
        next_page_token: "",
      }),
    ) as unknown as typeof fetch;

    render(<TenantsTable />);

    await waitFor(() => {
      expect(screen.getByTestId("tenants-row-t1-owner")).toBeInTheDocument();
    });

    const ownerCell = screen.getByTestId("tenants-row-t1-owner");
    const allowedContainer = ownerCell.querySelector('[data-i18n-allow="data"]');
    expect(allowedContainer).not.toBeNull();
    expect(allowedContainer?.textContent).toContain("Alice Liu");
  });
});


