      container.querySelector(".lucide-corner-down-right"),
    ).toBeInTheDocument();
    expect(container.textContent).not.toContain("└");
  });

  it("CornerDownRight connector icon is aria-hidden", async () => {
    globalThis.fetch = vi.fn(async () =>
      envelope({
        tenants: [makeOrg("org-1", "Acme"), makeWorkspace("ws-1", "Engineering", "org-1")],
