import { describe, expect, it } from "vitest";

import { orderTreeRows } from "../../src/tenants/tenantTree";
import type { AdminTenant } from "../../src/api/tenants";

function tenant(
  id: string,
  name: string,
  parent_id?: string,
): AdminTenant {
  return {
    id,
    name,
    slug: name.toLowerCase(),
    parent_id,
    created_at: "2026-05-12T12:00:00Z",
    updated_at: "2026-05-12T12:00:00Z",
    status: "active",
  };
}

describe("orderTreeRows", () => {
  it("sorts organizations alphabetically with their children below each", () => {
    const rows = orderTreeRows([
      tenant("g", "Globex"),
      tenant("a", "Acme"),
      tenant("a-east", "Acme East", "a"),
      tenant("a-west", "Acme West", "a"),
      tenant("g-eu", "Globex EU", "g"),
    ]);
    expect(rows.map((r) => `${"  ".repeat(r.depth)}${r.tenant.name}`)).toEqual([
      "Acme",
      "  Acme East",
      "  Acme West",
      "Globex",
      "  Globex EU",
    ]);
  });

  it("sorts children alphabetically under their parent (case-insensitive)", () => {
    const rows = orderTreeRows([
      tenant("a", "Acme"),
      tenant("c1", "beta", "a"),
      tenant("c2", "Alpha", "a"),
    ]);
    expect(rows.map((r) => r.tenant.name)).toEqual(["Acme", "Alpha", "beta"]);
  });

  it("emits depth=0 for orgs and depth=1 for children", () => {
    const rows = orderTreeRows([
      tenant("a", "Acme"),
      tenant("c", "Acme East", "a"),
    ]);
    expect(rows[0]?.depth).toBe(0);
    expect(rows[1]?.depth).toBe(1);
  });

  it("places orphan children (parent not in result set) at the tail at depth 0", () => {
    const rows = orderTreeRows([
      tenant("a", "Acme"),
      tenant("orphan", "Orphaned WS", "missing-parent"),
    ]);
    expect(rows.map((r) => r.tenant.name)).toEqual(["Acme", "Orphaned WS"]);
    expect(rows[1]?.depth).toBe(0);
  });

  it("returns empty for empty input", () => {
    expect(orderTreeRows([])).toEqual([]);
  });
});



